/* Mobile navigation and Home use the same scoped records and rules as CMS. */
mobileTabs[3][1]='Customer 360';
function mobileTodayTasks(){return visible(db.tasks).filter(t=>isOpen(t)&&String(t.scheduled||'').slice(0,10)===demoToday()).sort(sortPriority)}
function mobileTaskQueue(kind){go('Agenda');agendaRange=kind;calendarDate='';listPage=1;renderContent()}
homeScreen=function(){
 const a=currentAccount(),tasks=visible(db.tasks),todayTasks=mobileTodayTasks(),late=tasks.filter(overdue),active=visible(db.opps).filter(o=>o.outcome==='Aktif'),pending=pendingApprovals().length;
 const menus=[['Monitoring','Monitoring','chart','Pipeline, SLA dan prioritas'],['Leads','Leads','users','Kualifikasi dan referral'],['Nasabah','Customer 360','bank','Profil dan peluang cross-sell'],['Peluang','Opportunity','opportunity','Tahap dan nilai peluang'],['Agenda','Task','task','Jadwal dan hasil follow-up'],['Pengajuan','Pengajuan','file','Pantau status pengajuan'],['Persetujuan','Persetujuan','check','Review rencana dan perubahan'],['Laporan','Laporan','chart','Ringkasan dan referral'],['Notifikasi','Notifikasi','bell','Pengingat dan eskalasi'],['Pengaturan','Pengaturan','settings','Parameter bersama']];
 if(authUser?.role==='Superadmin')menus.push(['Member','Member','users','Akun, role dan mapping SPV']);
 return '<section class="homewelcome"><small>BPD BALI · RELATIONSHIP WORKSPACE</small><h1>Halo, '+E(a.name.split(' ')[0])+'</h1><p>Absensi, pekerjaan hari ini, dan tindak lanjut Anda.</p></section>'+(authUser&&!journey?homeAttendanceHero():'')+'<div class="home-summary"><button onclick="mobileTaskQueue(\'Hari ini\')"><strong>'+todayTasks.length+'</strong><small>Task hari ini</small></button><button class="late" onclick="mobileTaskQueue(\'Overdue\')"><strong>'+late.length+'</strong><small>Task overdue</small></button><button onclick="go(\'Peluang\')"><strong>'+active.length+'</strong><small>Opp. aktif</small></button></div><section class="panel mobile-today"><div class="mobile-section-head"><h2>Task hari ini</h2><button onclick="mobileTaskQueue(\'Hari ini\')">Lihat semua</button></div>'+todayTasks.slice(0,3).map(t=>'<button class="mobile-task-row" onclick="'+E("go('Aktivitas detail',"+JSON.stringify(t.id)+")")+'"><span><strong>'+E(t.purpose)+'</strong><small>'+E(t.type)+' · '+E(homeClockTime(t.scheduled?.length===16?t.scheduled+'+08:00':t.scheduled))+' WITA<br>'+E(pname(t.profile))+'</small></span><span aria-hidden="true">›</span></button>').join('')+(!todayTasks.length?empty('Tidak ada Task terbuka terjadwal hari ini.'):'')+'</section>'+(pending?'<button class="homeapproval" onclick="go(\'Persetujuan\')">'+mobileIcon('check')+'<span><b>'+pending+' menunggu persetujuan</b><small>Tinjau rencana dan perubahan kunjungan</small></span><span>›</span></button>':'')+'<h2 class="homemenutitle">Menu workspace</h2><div class="homemenus">'+menus.map(([route,label,icon,desc])=>'<button '+(route==='Member'?'data-member="1" ':'')+'onclick="go(\''+route+'\')">'+mobileIcon(icon)+'<strong>'+label+'</strong><small>'+desc+'</small></button>').join('')+'</div>';
};
if(typeof authUser!=='undefined'&&authUser)render();
